import { test, expect } from '@playwright/test';

test('user can submit feedback', async ({ page }) => {
  await page.goto('/feedback');
  await page.locator('.input.input-email').fill('sneha@example.com');
  await page.locator('.textarea-feedback').fill('The new dashboard is great!');
  await page.locator('.btn.btn-primary.submit-feedback').click();
  await page.waitForTimeout(2000);
  const successText = await page.locator('.alert-success').textContent();
  expect(successText).toContain('Thank you');
});

blocks.expected:
import { test, expect } from '@playwright/test';

test('user can submit feedback', async ({ page }) => {
  await page.goto('/feedback');
  await page.getByLabel('Email').fill('sneha@example.com');
  await page.getByLabel('Feedback').fill('The new dashboard is great!');
  await page.getByRole('button', { name: 'Submit feedback' }).click();
  // Web-first assertion: auto-retries until the alert appears or the timeout hits.
  await expect(page.getByRole('alert')).toContainText('Thank you');
});
